INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_YAZIDI','Yazidi tradition (formative reform to present)',1100,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_SPAT_YEZIDIS','secondary scholarship','Eszter Spat, The Yezidis (London: Saqi, 2005)','Yazidi religion, mythology, the Heptad, Tawusi Melek, Lalish, oral qewls'),
 ('SRC_KREYENBROEK_YEZIDISM','secondary scholarship','Philip G. Kreyenbroek, Yezidism: Its Background, Observances and Textual Tradition (Lewiston: Edwin Mellen Press, 1995)','Yazidi theology, the Seven Mysteries, Sheikh Adi, cosmology, hymn texts'),
 ('SRC_OMARKHALI_YEZIDI_TEXTUAL','secondary scholarship','Khanna Omarkhali, The Yezidi Religious Textual Tradition (Wiesbaden: Harrassowitz, 2017)','Yazidi sacred oral hymns (qewls and beyts), avatars of the Heptad, sheikhly and pir lineages')
INSERT INTO _e VALUES
 ('ENT_YAZ_HEPTAD','The Heptad (Haft Sirr / Seven Mysteries)','Angelic collective','Angelic Collective','Yazidi','divine governance; emanation; cosmic administration','B','Attested in Spat and Kreyenbroek as the Seven Angels/Mysteries to whom Xwede entrusted the world; hub of Yazidi cosmology.'),
 ('ENT_YAZ_XWEDE','Xwede','Supreme deity','Supreme deity','Yazidi','creation; transcendence; the remote One God','B','The single remote creator God in Yazidi belief who delegates the cosmos to the Heptad; attested across Kreyenbroek and Spat.'),
 ('ENT_YAZ_TAWUSI_MELEK','Tawusi Melek (Melek Taus, the Peacock Angel)','Angel','Angelic Being','Yazidi','chief of the Heptad; divine vicegerent; mediator','B','Chief of the Seven; venerated as God''s foremost emanation and steward of the world. Yazidis REJECT the external misidentification with Shaytan/the devil; modeled here only as the Peacock Angel of the qewls (Spat, Kreyenbroek).'),
 ('ENT_YAZ_SHEIKH_ADI','Sheikh Adi ibn Musafir','Sufi saint','Sufi saint (wali)','Yazidi','reformer; manifestation of the divine; sheikhly lineage','B','Historical 12th-c. Sufi ascetic of Hakkari (d. c.1162) whose tomb is at Lalish; revered in Yazidism as a supreme manifestation and reorganizer of the faith (Kreyenbroek).'),
 ('ENT_YAZ_SULTAN_EZID','Sultan Ezid (Sultan Ezi)','Divine manifestation','Holy Figure','Yazidi','manifestation of the divine; eponymous holy figure','C','Revered manifestation/holy figure central to Yazidi devotion, often linked in name-tradition to the community''s self-designation; attested in the qewls (Spat, Kreyenbroek).'),
 ('ENT_YAZ_SHEIKH_HASAN','Sheikh Hasan (Sheikh Sin)','Angel','Holy Figure','Yazidi','member of the Heptad; sheikhly lineage; scribe/wisdom associations','C','One of the Seven Mysteries and an earthly avatar; eponym of a principal sheikhly lineage (Kreyenbroek, Omarkhali).'),
 ('ENT_YAZ_SHEIKH_SHAMS','Sheikh Shams (Shams al-Din)','Solar deity','Solar Deity','Yazidi','the sun; light; member of the Heptad','C','Member of the Seven associated with the sun and light; receives dawn veneration in Yazidi practice; eponym of a sheikhly lineage (Spat, Kreyenbroek).'),
 ('ENT_YAZ_FAKHR_AL_DIN','Sheikh Fakhr al-Din','Angel','Holy Figure','Yazidi','member of the Heptad; cosmogonic/creative role','C','One of the Seven Mysteries, with a creative/cosmogonic role in the qewls; eponym of a sheikhly lineage. Distinct from the Sufi poet Fakhr al-Din Iraqi (homonym) (Kreyenbroek, Omarkhali).'),
 ('ENT_YAZ_SAJADIN','Sheikh Sajadin (Sejadin)','Angel','Holy Figure','Yazidi','member of the Heptad; sheikhly lineage','C','One of the Seven Mysteries / Sons of Sheikh Adi''s companions in the qewls; eponym of a sheikhly lineage (Kreyenbroek, Omarkhali).'),
 ('ENT_YAZ_NASIRDIN','Sheikh Nasirdin (Nasr al-Din)','Angel','Holy Figure','Yazidi','member of the Heptad; sheikhly lineage','C','One of the Seven Mysteries and eponym of a sheikhly lineage in the Yazidi oral tradition (Kreyenbroek, Omarkhali).'),
 ('ENT_YAZ_SHEIKH_OBEKR','Sheikh Obekr (Abu Bakr)','Angel','Holy Figure','Yazidi','member of the Heptad; sheikhly lineage','C','Counted among the Seven Mysteries in several enumerations; eponym of a Yazidi sheikhly lineage (Kreyenbroek). Note: distinct from the Islamic caliph despite the shared name (homonym).'),
 ('ENT_YAZ_LALISH','Lalish','Sacred Place','Sacred Place','Yazidi','holy valley; pilgrimage center; cosmic axis','B','The sacred valley north of Mosul housing Sheikh Adi''s tomb; supreme Yazidi pilgrimage site and a sanctified cosmic realm in the qewls (Spat, Kreyenbroek).'),
 ('ENT_YAZ_PIR_LIBNAN','Pir Libnan (Pir Reshe / building master)','Holy figure','Holy Figure','Yazidi','sacred craft; building of Lalish; pir lineage','C','Holy figure of the pir caste associated in the qewls with the sacred construction at Lalish; eponym of a pir lineage (Kreyenbroek).'),
 ('ENT_YAZ_MEHMA_RESHAN','Pir Mehma Reshan','Holy figure','Holy Figure','Yazidi','weather/storm associations; pir lineage','C','Revered pir-lineage holy figure of the Yazidi oral tradition, with storm/weather associations in some qewls (Omarkhali, Kreyenbroek).'),
 ('ENT_YAZ_KHATUNA_FAKHRA','Khatuna Fakhra','Holy figure','Holy Figure','Yazidi','midwifery; protection of mothers and children; revered woman','C','Venerated female holy figure invoked as a patroness of childbirth and protection of infants in Yazidi devotion (Spat).');
