INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_YAZ_TAWUSI_MELEK','member_of','ENT_YAZ_HEPTAD','high','Tawusi Melek is the chief of the Seven Mysteries/Heptad (Spat, Kreyenbroek).'),
 ('ENT_YAZ_SHEIKH_ADI','member_of','ENT_YAZ_HEPTAD','medium','Sheikh Adi is counted among the manifestations of the Heptad in the qewls (Kreyenbroek).'),
 ('ENT_YAZ_SHEIKH_HASAN','member_of','ENT_YAZ_HEPTAD','high','Sheikh Hasan (Sheikh Sin) is one of the Seven Mysteries (Kreyenbroek, Omarkhali).'),
 ('ENT_YAZ_SHEIKH_SHAMS','member_of','ENT_YAZ_HEPTAD','high','Sheikh Shams is one of the Seven, associated with the sun (Spat, Kreyenbroek).'),
 ('ENT_YAZ_FAKHR_AL_DIN','member_of','ENT_YAZ_HEPTAD','high','Sheikh Fakhr al-Din is one of the Seven Mysteries (Kreyenbroek, Omarkhali).'),
 ('ENT_YAZ_SAJADIN','member_of','ENT_YAZ_HEPTAD','medium','Sheikh Sajadin is enumerated among the Seven Mysteries in the qewls (Kreyenbroek, Omarkhali).'),
 ('ENT_YAZ_NASIRDIN','member_of','ENT_YAZ_HEPTAD','medium','Sheikh Nasirdin is enumerated among the Seven Mysteries in the qewls (Kreyenbroek, Omarkhali).'),
 ('ENT_YAZ_SHEIKH_OBEKR','member_of','ENT_YAZ_HEPTAD','medium','Sheikh Obekr appears among the Seven in several enumerations of the Heptad (Kreyenbroek).'),
 ('ENT_YAZ_HEPTAD','emanates_from','ENT_YAZ_XWEDE','high','Xwede, the remote creator, brings forth and delegates the world to the Heptad (Kreyenbroek).'),
 ('ENT_YAZ_TAWUSI_MELEK','emanates_from','ENT_YAZ_XWEDE','high','Tawusi Melek is the foremost emanation/vicegerent of Xwede (Spat, Kreyenbroek).'),
 ('ENT_YAZ_HEPTAD','rules','ENT_YAZ_LALISH','medium','The Heptad and especially Sheikh Adi govern the sanctified realm of Lalish in Yazidi cosmology (Spat).'),
 ('ENT_YAZ_SHEIKH_ADI','dwells_in','ENT_YAZ_LALISH','high','Sheikh Adi''s tomb is at Lalish, the supreme pilgrimage center (Spat, Kreyenbroek).'),
 ('ENT_YAZ_PIR_LIBNAN','associated_with','ENT_YAZ_LALISH','medium','Pir Libnan is associated in the qewls with the sacred building of Lalish (Kreyenbroek).'),
 ('ENT_YAZ_SULTAN_EZID','member_of','ENT_YAZ_HEPTAD','medium','Sultan Ezid is a divine manifestation closely woven into the Heptad theology of the qewls (Spat, Kreyenbroek).'),
 ('ENT_YAZ_MEHMA_RESHAN','associated_with','ENT_YAZ_HEPTAD','low','Pir Mehma Reshan figures among the holy pir lineages tied to the Heptad''s earthly manifestations (Omarkhali, Kreyenbroek).'),
 ('ENT_YAZ_KHATUNA_FAKHRA','associated_with','ENT_YAZ_SHEIKH_ADI','low','Khatuna Fakhra is a revered woman of the Adani holy circle in Yazidi devotion (Spat).'),
 ('ENT_YAZ_SHEIKH_ADI','reception_of','ENT_SUF_JILANI','medium','Sheikh Adi ibn Musafir was a historical Sufi ascetic of the Qadiri-adjacent Baghdad milieu of Abd al-Qadir al-Jilani; Yazidism received him as a supreme manifestation (Kreyenbroek).'),
 ('ENT_YAZ_TAWUSI_MELEK','aligned_with','ENT_SUF_HALLAJ','low','The Yazidi exaltation of the foremost angel echoes the Sufi (Hallajian) defense of Iblis''s refusal to bow as supreme love/obedience to God alone; a theological parallel, not an identification (Spat).'),
 ('ENT_YAZ_TAWUSI_MELEK','opposes','ENT_ISL_SHAYTAN','medium','Yazidis explicitly reject the external conflation of Tawusi Melek with Shaytan/the devil; modeled here to record that the misidentification is repudiated, not affirmed (Spat, Kreyenbroek).'),
 ('ENT_YAZ_SHEIKH_SHAMS','aligned_with','ENT_AST_SUN_SPIRIT','low','Sheikh Shams embodies solar veneration in Yazidism, functionally parallel to the sun-spirit of astral/planetary traditions (Kreyenbroek); cognate alignment, not identity.');
